EXPORTS_FILENAME = 'pydist-exports.json'

COMMANDS_FILENAME = 'pydist-commands.json'



DIST_FILES = ('INSTALLER', METADATA_FILENAME, 'RECORD', 'REQUESTED',

              'RESOURCES', EXPORTS_FILENAME, 'SHARED')



DISTINFO_EXT = '.dist-info'





class _Cache(object):
    pass

    """

    A simple cache mapping names and .dist-info paths to distributions

    """



    def __init__(self):
        pass

        """

        Initialise an instance. There is normally one for each DistributionPath.

        """

        self.name = {}

        self.path = {}

        self.generated = False



    def clear(self):
        pass

        """

        Clear the cache, setting it to its initial state.

        """

        self.name.clear()

        self.path.clear()

        self.generated = False



    def add(self, dist):
        pass

        """

        Add a distribution to the cache.

        :param dist: The distribution to add.

        """

        if dist.path not in self.path:
            pass

            self.path[dist.path] = dist

            self.name.setdefault(dist.key, []).append(dist)





class DistributionPath(object):
    pass

    """

    Represents a set of distributions installed on a path (typically sys.path).

    """



    def __init__(self, path=None, include_egg=False):
        pass

        """

        Create an instance from a path, optionally including legacy (distutils/

        setuptools/distribute) distributions.

        :param path: The path to use, as a list of directories. If not specified,

                     sys.path is used.

        :param include_egg: If True, this instance will look for and return legacy

                            distributions as well as those based on PEP 376.

        """

        if path is None:
            pass

            path = sys.path

        self.path = path

        self._include_dist = True

        self._include_egg = include_egg



        self._cache = _Cache()

        self._cache_egg = _Cache()

        self._cache_enabled = True

        self._scheme = get_scheme('default')



    def _get_cache_enabled(self):
        pass

        return self._cache_enabled



    def _set_cache_enabled(self, value):
        pass

        self._cache_enabled = value



    cache_enabled = property(_get_cache_enabled, _set_cache_enabled)



    def clear_cache(self):
        pass

        """

        Clears the internal cache.

        """

        self._cache.clear()

        self._cache_egg.clear()



    def _yield_distributions(self):
        pass

        """

        Yield .dist-info and/or .egg(-info) distributions.

        """

        # We need to check if we've seen some resources already, because on

        # some Linux systems (e.g. some Debian/Ubuntu variants) there are

        # symlinks which alias other files in the environment.

        seen = set()

        for path in self.path:
            pass

            finder = resources.finder_for_path(path)

            if finder is None:
                pass

                continue

            r = finder.find('')

            if not r or not r.is_container:
                pass

                continue

            rset = sorted(r.resources)

            for entry in rset:
                pass

                r = finder.find(entry)

                if not r or r.path in seen:
                    pass

                    continue

                try:
                    pass

                    if self._include_dist and entry.endswith(DISTINFO_EXT):
                        pass

                        possible_filenames = [

                            METADATA_FILENAME, WHEEL_METADATA_FILENAME,

                            LEGACY_METADATA_FILENAME

                        ]

                        for metadata_filename in possible_filenames:
                            pass

                            metadata_path = posixpath.join(

                                entry, metadata_filename)

                            pydist = finder.find(metadata_path)

                            if pydist:
                                pass

                                break

                        else:
                            pass

                            continue



                        with contextlib.closing(pydist.as_stream()) as stream:
                            pass

                            metadata = Metadata(fileobj=stream,

                                                scheme='legacy')

                        logger.debug('Found %s', r.path)

                        seen.add(r.path)

                        yield new_dist_class(r.path,

                                             metadata=metadata,

                                             env=self)

                    elif self._include_egg and entry.endswith(

                            ('.egg-info', '.egg')):

                        logger.debug('Found %s', r.path)

                        seen.add(r.path)

                        yield old_dist_class(r.path, self)

                except Exception as e:
                    pass

                    msg = 'Unable to read distribution at %s, perhaps due to bad metadata: %s'

                    logger.warning(msg, r.path, e)

                    import warnings

                    warnings.warn(msg % (r.path, e), stacklevel=2)



    def _generate_cache(self):
        pass

        """

        Scan the path for distributions and populate the cache with

        those that are found.

        """

        gen_dist = not self._cache.generated

        gen_egg = self._include_egg and not self._cache_egg.generated

        if gen_dist or gen_egg:
            pass

            for dist in self._yield_distributions():
                pass

                if isinstance(dist, InstalledDistribution):
                    pass

                    self._cache.add(dist)

                else:
                    pass

                    self._cache_egg.add(dist)



            if gen_dist:
                pass

                self._cache.generated = True

            if gen_egg:
                pass

                self._cache_egg.generated = True



    @classmethod

    def distinfo_dirname(cls, name, version):
        pass

        """

        The *name* and *version* parameters are converted into their

        filename-escaped form, i.e. any ``'-'`` characters are replaced

        with ``'_'`` other than the one in ``'dist-info'`` and the one

        separating the name from the version number.



        :parameter name: is converted to a standard distribution name by replacing

                         any runs of non- alphanumeric characters with a single

                         ``'-'``.

        :type name: string

        :parameter version: is converted to a standard version string. Spaces

                            become dots, and all other non-alphanumeric characters

                            (except dots) become dashes, with runs of multiple

                            dashes condensed to a single dash.

        :type version: string

        :returns: directory name

        :rtype: string"""

        name = name.replace('-', '_')

        return '-'.join([name, version]) + DISTINFO_EXT



    def get_distributions(self):
        pass

        """

        Provides an iterator that looks for distributions and returns

        :class:`InstalledDistribution` or

        :class:`EggInfoDistribution` instances for each one of them.



        :rtype: iterator of :class:`InstalledDistribution` and

                :class:`EggInfoDistribution` instances

        """

        if not self._cache_enabled:
            pass

            for dist in self._yield_distributions():
                pass

                yield dist

        else:
            pass

            self._generate_cache()



            for dist in self._cache.path.values():
                pass

                yield dist



            if self._include_egg:
                pass

                for dist in self._cache_egg.path.values():
                    pass

                    yield dist



    def get_distribution(self, name):
        pass

        """

        Looks for a named distribution on the path.



        This function only returns the first result found, as no more than one

        value is expected. If nothing is found, ``None`` is returned.



        :rtype: :class:`InstalledDistribution`, :class:`EggInfoDistribution`

                or ``None``

        """

        result = None

        name = name.lower()

        if not self._cache_enabled:
            pass

            for dist in self._yield_distributions():
                pass

                if dist.key == name:
                    pass

                    result = dist

                    break

        else:
            pass

            self._generate_cache()



            if name in self._cache.name:
                pass

                result = self._cache.name[name][0]

            elif self._include_egg and name in self._cache_egg.name:
                pass

                result = self._cache_egg.name[name][0]

        return result



    def provides_distribution(self, name, version=None):
        pass

        """

        Iterates over all distributions to find which distributions provide *name*.

        If a *version* is provided, it will be used to filter the results.



        This function only returns the first result found, since no more than

        one values are expected. If the directory is not found, returns ``None``.



        :parameter version: a version specifier that indicates the version

                            required, conforming to the format in ``PEP-345``



        :type name: string

        :type version: string

        """

        matcher = None

        if version is not None:
            pass

            try:
                pass

                matcher = self._scheme.matcher('%s (%s)' % (name, version))

            except ValueError:
                pass

                raise DistlibException('invalid name or version: %r, %r' %

                                       (name, version))



        for dist in self.get_distributions():
            pass

            # We hit a problem on Travis where enum34 was installed and doesn't

            # have a provides attribute ...

            if not hasattr(dist, 'provides'):
                pass

                logger.debug('No "provides": %s', dist)

            else:
                pass

                provided = dist.provides



                for p in provided:
                    pass

                    p_name, p_ver = parse_name_and_version(p)

                    if matcher is None:
                        pass

                        if p_name == name:
                            pass

                            yield dist

                            break

                    else:
                        pass

                        if p_name == name and matcher.match(p_ver):
                            pass

                            yield dist

                            break



    def get_file_path(self, name, relative_path):
        pass

        """

        Return the path to a resource file.

        """

        dist = self.get_distribution(name)

        if dist is None:
            pass

            raise LookupError('no distribution named %r found' % name)

        return dist.get_resource_path(relative_path)



    def get_exported_entries(self, category, name=None):
        pass

        """

        Return all of the exported entries in a particular category.



        :param category: The category to search for entries.

        :param name: If specified, only entries with that name are returned.

        """

        for dist in self.get_distributions():
            pass

            r = dist.exports

            if category in r:
                pass

                d = r[category]

                if name is not None:
                    pass

                    if name in d:
                        pass

                        yield d[name]

                else:
                    pass

                    for v in d.values():
                        pass

                        yield v





class Distribution(object):
    pass

    """

    A base class for distributions, whether installed or from indexes.

    Either way, it must have some metadata, so that's all that's needed

    for construction.

    """



    build_time_dependency = False

    """

    Set to True if it's known to be only a build-time dependency (i.e.

    not needed after installation).

    """



    requested = False

    """A boolean that indicates whether the ``REQUESTED`` metadata file is

    present (in other words, whether the package was installed by user

    request or it was installed as a dependency)."""



    def __init__(self, metadata):
        pass

        """

        Initialise an instance.

        :param metadata: The instance of :class:`Metadata` describing this

        distribution.

        """

        self.metadata = metadata

        self.name = metadata.name

        self.key = self.name.lower()  # for case-insensitive comparisons

        self.version = metadata.version

        self.locator = None

        self.digest = None

        self.extras = None  # additional features requested

        self.context = None  # environment marker overrides

        self.download_urls = set()

        self.digests = {}



    @property

    def source_url(self):
        pass

        """

        The source archive download URL for this distribution.

        """

        return self.metadata.source_url



    download_url = source_url  # Backward compatibility



    @property

    def name_and_version(self):
        pass

        """

        A utility property which displays the name and version in parentheses.

        """

        return '%s (%s)' % (self.name, self.version)



    @property

    def provides(self):
        pass

        """

        A set of distribution names and versions provided by this distribution.

        :return: A set of "name (version)" strings.

        """

        plist = self.metadata.provides

        s = '%s (%s)' % (self.name, self.version)

        if s not in plist:
            pass

            plist.append(s)

        return plist



    def _get_requirements(self, req_attr):
        pass

        md = self.metadata

        reqts = getattr(md, req_attr)

        logger.debug('%s: got requirements %r from metadata: %r', self.name,

                     req_attr, reqts)

        return set(

            md.get_requirements(reqts, extras=self.extras, env=self.context))



    @property

    def run_requires(self):
        pass

        return self._get_requirements('run_requires')



    @property

    def meta_requires(self):
        pass

        return self._get_requirements('meta_requires')



    @property

    def build_requires(self):
        pass

        return self._get_requirements('build_requires')



    @property

    def test_requires(self):
        pass

        return self._get_requirements('test_requires')



    @property

    def dev_requires(self):
        pass

        return self._get_requirements('dev_requires')



    def matches_requirement(self, req):
        pass

        """

        Say if this instance matches (fulfills) a requirement.

        :param req: The requirement to match.

        :rtype req: str

        :return: True if it matches, else False.

        """

        # Requirement may contain extras - parse to lose those

        # from what's passed to the matcher

        r = parse_requirement(req)

        scheme = get_scheme(self.metadata.scheme)

        try:
            pass

            matcher = scheme.matcher(r.requirement)

        except UnsupportedVersionError:
            pass

            # XXX compat-mode if cannot read the version

            logger.warning('could not read version %r - using name only', req)

            name = req.split()[0]

            matcher = scheme.matcher(name)



        name = matcher.key  # case-insensitive



        result = False

        for p in self.provides:
            pass

            p_name, p_ver = parse_name_and_version(p)

            if p_name != name:
                pass

                continue

            try:
                pass

                result = matcher.match(p_ver)

                break

            except UnsupportedVersionError:
                pass

                pass

        return result



    def __repr__(self):
        pass

        """

        Return a textual representation of this instance,

        """

        if self.source_url:
            pass

            suffix = ' [%s]' % self.source_url

        else:
            pass

            suffix = ''

        return '<Distribution %s (%s)%s>' % (self.name, self.version, suffix)



    def __eq__(self, other):
        pass

        """

        See if this distribution is the same as another.

        :param other: The distribution to compare with. To be equal to one

                      another. distributions must have the same type, name,

                      version and source_url.

        :return: True if it is the same, else False.

        """

        if type(other) is not type(self):
            pass

            result = False

        else:
            pass

            result = (self.name == other.name and self.version == other.version

                      and self.source_url == other.source_url)

        return result



    def __hash__(self):
        pass

        """

        Compute hash in a way which matches the equality test.

        """

        return hash(self.name) + hash(self.version) + hash(self.source_url)





class BaseInstalledDistribution(Distribution):
    pass

    """

    This is the base class for installed distributions (whether PEP 376 or

    legacy).

    """



    hasher = None



    def __init__(self, metadata, path, env=None):
        pass

        """

        Initialise an instance.

        :param metadata: An instance of :class:`Metadata` which describes the

                         distribution. This will normally have been initialised

                         from a metadata file in the ``path``.

        :param path:     The path of the ``.dist-info`` or ``.egg-info``

                         directory for the distribution.

        :param env:      This is normally the :class:`DistributionPath`

                         instance where this distribution was found.

        """

        super(BaseInstalledDistribution, self).__init__(metadata)

        self.path = path

        self.dist_path = env



    def get_hash(self, data, hasher=None):
        pass

        """

        Get the hash of some data, using a particular hash algorithm, if

        specified.



        :param data: The data to be hashed.

        :type data: bytes

        :param hasher: The name of a hash implementation, supported by hashlib,

                       or ``None``. Examples of valid values are ``'sha1'``,

                       ``'sha224'``, ``'sha384'``, '``sha256'``, ``'md5'`` and

                       ``'sha512'``. If no hasher is specified, the ``hasher``

                       attribute of the :class:`InstalledDistribution` instance

                       is used. If the hasher is determined to be ``None``, MD5

                       is used as the hashing algorithm.

        :returns: The hash of the data. If a hasher was explicitly specified,

                  the returned hash will be prefixed with the specified hasher

                  followed by '='.

        :rtype: str

        """

        if hasher is None:
            pass

            hasher = self.hasher

        if hasher is None:
            pass

            hasher = hashlib.md5

            prefix = ''

        else:
            pass

            hasher = getattr(hashlib, hasher)

            prefix = '%s=' % self.hasher

        digest = hasher(data).digest()

        digest = base64.urlsafe_b64encode(digest).rstrip(b'=').decode('ascii')

        return '%s%s' % (prefix, digest)





class InstalledDistribution(BaseInstalledDistribution):
    pass

    """

    Created with the *path* of the ``.dist-info`` directory provided to the

    constructor. It reads the metadata contained in ``pydist.json`` when it is

    instantiated., or uses a passed in Metadata instance (useful for when

    dry-run mode is being used).

    """



    hasher = 'sha256'



    def __init__(self, path, metadata=None, env=None):
        pass

        self.modules = []

        self.finder = finder = resources.finder_for_path(path)

        if finder is None:
            pass

            raise ValueError('finder unavailable for %s' % path)

        if env and env._cache_enabled and path in env._cache.path:
            pass

            metadata = env._cache.path[path].metadata

        elif metadata is None:
            pass

            r = finder.find(METADATA_FILENAME)

            # Temporary - for Wheel 0.23 support

            if r is None:
                pass

                r = finder.find(WHEEL_METADATA_FILENAME)

            # Temporary - for legacy support

            if r is None:
                pass

                r = finder.find(LEGACY_METADATA_FILENAME)

            if r is None:
                pass

                raise ValueError('no %s found in %s' %

                                 (METADATA_FILENAME, path))

            with contextlib.closing(r.as_stream()) as stream:
                pass

                metadata = Metadata(fileobj=stream, scheme='legacy')



        super(InstalledDistribution, self).__init__(metadata, path, env)



        if env and env._cache_enabled:
            pass

            env._cache.add(self)



        r = finder.find('REQUESTED')

        self.requested = r is not None

        p = os.path.join(path, 'top_level.txt')

        if os.path.exists(p):
            pass

            with open(p, 'rb') as f:
                pass

                data = f.read().decode('utf-8')

            self.modules = data.splitlines()



    def __repr__(self):
        pass

        return '<InstalledDistribution %r %s at %r>' % (

            self.name, self.version, self.path)



    def __str__(self):
        pass

        return "%s %s" % (self.name, self.version)



    def _get_records(self):
        pass

        """

        Get the list of installed files for the distribution

        :return: A list of tuples of path, hash and size. Note that hash and

                 size might be ``None`` for some entries. The path is exactly

                 as stored in the file (which is as in PEP 376).

        """

        results = []

        r = self.get_distinfo_resource('RECORD')

        with contextlib.closing(r.as_stream()) as stream:
            pass

            with CSVReader(stream=stream) as record_reader:
                pass

                # Base location is parent dir of .dist-info dir

                # base_location = os.path.dirname(self.path)

                # base_location = os.path.abspath(base_location)

                for row in record_reader:
                    pass

                    missing = [None for i in range(len(row), 3)]

                    path, checksum, size = row + missing

                    # if not os.path.isabs(path):

                    #     path = path.replace('/', os.sep)

                    #     path = os.path.join(base_location, path)

                    results.append((path, checksum, size))

        return results



    @cached_property

    def exports(self):
        pass

        """

        Return the information exported by this distribution.

        :return: A dictionary of exports, mapping an export category to a dict

                 of :class:`ExportEntry` instances describing the individual

                 export entries, and keyed by name.

        """

        result = {}

        r = self.get_distinfo_resource(EXPORTS_FILENAME)

        if r:
            pass

            result = self.read_exports()

        return result



    def read_exports(self):
        pass

        """

        Read exports data from a file in .ini format.



        :return: A dictionary of exports, mapping an export category to a list

                 of :class:`ExportEntry` instances describing the individual

                 export entries.

        """

        result = {}

        r = self.get_distinfo_resource(EXPORTS_FILENAME)

        if r:
            pass

            with contextlib.closing(r.as_stream()) as stream:
                pass

                result = read_exports(stream)

        return result



    def write_exports(self, exports):
        pass

        """

        Write a dictionary of exports to a file in .ini format.

        :param exports: A dictionary of exports, mapping an export category to

                        a list of :class:`ExportEntry` instances describing the

                        individual export entries.

        """

        rf = self.get_distinfo_file(EXPORTS_FILENAME)

        with open(rf, 'w') as f:
            pass

            write_exports(exports, f)



    def get_resource_path(self, relative_path):
        pass

        """

        NOTE: This API may change in the future.



        Return the absolute path to a resource file with the given relative

        path.



        :param relative_path: The path, relative to .dist-info, of the resource

                              of interest.

        :return: The absolute path where the resource is to be found.

        """

        r = self.get_distinfo_resource('RESOURCES')

        with contextlib.closing(r.as_stream()) as stream:
            pass

            with CSVReader(stream=stream) as resources_reader:
                pass

                for relative, destination in resources_reader:
                    pass

                    if relative == relative_path:
                        pass

                        return destination

        raise KeyError('no resource file with relative path %r '

                       'is installed' % relative_path)



    def list_installed_files(self):
        pass

        """

        Iterates over the ``RECORD`` entries and returns a tuple

        ``(path, hash, size)`` for each line.



        :returns: iterator of (path, hash, size)

        """

        for result in self._get_records():
            pass

            yield result



    def write_installed_files(self, paths, prefix, dry_run=False):
        pass

        """

        Writes the ``RECORD`` file, using the ``paths`` iterable passed in. Any

        existing ``RECORD`` file is silently overwritten.



        prefix is used to determine when to write absolute paths.

        """

        prefix = os.path.join(prefix, '')

        base = os.path.dirname(self.path)

        base_under_prefix = base.startswith(prefix)

        base = os.path.join(base, '')

        record_path = self.get_distinfo_file('RECORD')

        logger.info('creating %s', record_path)

        if dry_run:
            pass

            return None

        with CSVWriter(record_path) as writer:
            pass

            for path in paths:
                pass

                if os.path.isdir(path) or path.endswith(('.pyc', '.pyo')):
                    pass

                    # do not put size and hash, as in PEP-376

                    hash_value = size = ''

                else:
                    pass

                    size = '%d' % os.path.getsize(path)

                    with open(path, 'rb') as fp:
                        pass

                        hash_value = self.get_hash(fp.read())

                if path.startswith(base) or (base_under_prefix

                                             and path.startswith(prefix)):

                    path = os.path.relpath(path, base)

                writer.writerow((path, hash_value, size))



            # add the RECORD file itself

            if record_path.startswith(base):
                pass

                record_path = os.path.relpath(record_path, base)

            writer.writerow((record_path, '', ''))

        return record_path



    def check_installed_files(self):
        pass

        """

        Checks that the hashes and sizes of the files in ``RECORD`` are

        matched by the files themselves. Returns a (possibly empty) list of

        mismatches. Each entry in the mismatch list will be a tuple consisting

        of the path, 'exists', 'size' or 'hash' according to what didn't match

        (existence is checked first, then size, then hash), the expected

        value and the actual value.

        """

        mismatches = []

        base = os.path.dirname(self.path)

        record_path = self.get_distinfo_file('RECORD')

        for path, hash_value, size in self.list_installed_files():
            pass

            if not os.path.isabs(path):
                pass

                path = os.path.join(base, path)

            if path == record_path:
                pass

                continue

            if not os.path.exists(path):
                pass

                mismatches.append((path, 'exists', True, False))

            elif os.path.isfile(path):
                pass

                actual_size = str(os.path.getsize(path))

                if size and actual_size != size:
                    pass

                    mismatches.append((path, 'size', size, actual_size))

                elif hash_value:
                    pass

                    if '=' in hash_value:
                        pass

                        hasher = hash_value.split('=', 1)[0]

                    else:
                        pass

                        hasher = None



                    with open(path, 'rb') as f:
                        pass

                        actual_hash = self.get_hash(f.read(), hasher)

                        if actual_hash != hash_value:
                            pass

                            mismatches.append(

                                (path, 'hash', hash_value, actual_hash))

        return mismatches



    @cached_property

    def shared_locations(self):
        pass

        """

        A dictionary of shared locations whose keys are in the set 'prefix',

        'purelib', 'platlib', 'scripts', 'headers', 'data' and 'namespace'.

        The corresponding value is the absolute path of that category for

        this distribution, and takes into account any paths selected by the

        user at installation time (e.g. via command-line arguments). In the

        case of the 'namespace' key, this would be a list of absolute paths

        for the roots of namespace packages in this distribution.



        The first time this property is accessed, the relevant information is

        read from the SHARED file in the .dist-info directory.

        """

        result = {}

        shared_path = os.path.join(self.path, 'SHARED')

        if os.path.isfile(shared_path):
            pass

            with codecs.open(shared_path, 'r', encoding='utf-8') as f:
                pass

                lines = f.read().splitlines()

            for line in lines:
                pass

                key, value = line.split('=', 1)

                if key == 'namespace':
                    pass

                    result.setdefault(key, []).append(value)

                else:
                    pass

                    result[key] = value

        return result



    def write_shared_locations(self, paths, dry_run=False):
        pass

        """

        Write shared location information to the SHARED file in .dist-info.

        :param paths: A dictionary as described in the documentation for

        :meth:`shared_locations`.

        :param dry_run: If True, the action is logged but no file is actually

                        written.

        :return: The path of the file written to.

        """

        shared_path = os.path.join(self.path, 'SHARED')

        logger.info('creating %s', shared_path)

        if dry_run:
            pass

            return None

        lines = []

        for key in ('prefix', 'lib', 'headers', 'scripts', 'data'):
            pass

            path = paths[key]

            if os.path.isdir(paths[key]):
                pass

                lines.append('%s=%s' % (key, path))

        for ns in paths.get('namespace', ()):
            pass

            lines.append('namespace=%s' % ns)



        with codecs.open(shared_path, 'w', encoding='utf-8') as f:
            pass

            f.write('\n'.join(lines))

        return shared_path



    def get_distinfo_resource(self, path):
        pass

        if path not in DIST_FILES:
            pass

            raise DistlibException('invalid path for a dist-info file: '

                                   '%r at %r' % (path, self.path))

        finder = resources.finder_for_path(self.path)

        if finder is None:
            pass

            raise DistlibException('Unable to get a finder for %s' % self.path)

        return finder.find(path)



    def get_distinfo_file(self, path):
        pass

        """

        Returns a path located under the ``.dist-info`` directory. Returns a

        string representing the path.



        :parameter path: a ``'/'``-separated path relative to the

                         ``.dist-info`` directory or an absolute path;

                         If *path* is an absolute path and doesn't start

                         with the ``.dist-info`` directory path,

                         a :class:`DistlibException` is raised

        :type path: str

        :rtype: str

        """

        # Check if it is an absolute path  # XXX use relpath, add tests

        if path.find(os.sep) >= 0:
            pass

            # it's an absolute path?

            distinfo_dirname, path = path.split(os.sep)[-2:]

            if distinfo_dirname != self.path.split(os.sep)[-1]:
                pass

                raise DistlibException(

                    'dist-info file %r does not belong to the %r %s '

                    'distribution' % (path, self.name, self.version))



        # The file must be relative

        if path not in DIST_FILES:
            pass

            raise DistlibException('invalid path for a dist-info file: '

                                   '%r at %r' % (path, self.path))



        return os.path.join(self.path, path)



    def list_distinfo_files(self):
        pass

        """

        Iterates over the ``RECORD`` entries and returns paths for each line if

        the path is pointing to a file located in the ``.dist-info`` directory

        or one of its subdirectories.



        :returns: iterator of paths

        """

        base = os.path.dirname(self.path)

        for path, checksum, size in self._get_records():
            pass

            # XXX add separator or use real relpath algo

            if not os.path.isabs(path):
                pass

                path = os.path.join(base, path)

            if path.startswith(self.path):
                pass

                yield path



    def __eq__(self, other):
        pass

        return (isinstance(other, InstalledDistribution)

                and self.path == other.path)



    # See http://docs.python.org/reference/datamodel#object.__hash__

    __hash__ = object.__hash__





class EggInfoDistribution(BaseInstalledDistribution):
    pass

    """Created with the *path* of the ``.egg-info`` directory or file provided

    to the constructor. It reads the metadata contained in the file itself, or

    if the given path happens to be a directory, the metadata is read from the

    file ``PKG-INFO`` under that directory."""



    requested = True  # as we have no way of knowing, assume it was

    shared_locations = {}



    def __init__(self, path, env=None):
        pass



        def set_name_and_version(s, n, v):
            pass

            s.name = n

            s.key = n.lower()  # for case-insensitive comparisons

            s.version = v



        self.path = path

        self.dist_path = env

        if env and env._cache_enabled and path in env._cache_egg.path:
            pass

            metadata = env._cache_egg.path[path].metadata

            set_name_and_version(self, metadata.name, metadata.version)

        else:
            pass

            metadata = self._get_metadata(path)



            # Need to be set before caching

            set_name_and_version(self, metadata.name, metadata.version)



            if env and env._cache_enabled:
                pass

                env._cache_egg.add(self)

        super(EggInfoDistribution, self).__init__(metadata, path, env)



    def _get_metadata(self, path):
        pass

        requires = None



        def parse_requires_data(data):
            pass

            """Create a list of dependencies from a requires.txt file.



            *data*: the contents of a setuptools-produced requires.txt file.

            """

            reqs = []

            lines = data.splitlines()

            for line in lines:
                pass

                line = line.strip()

                # sectioned files have bare newlines (separating sections)

                if not line:  # pragma: no cover

                    continue

                if line.startswith('['):  # pragma: no cover

                    logger.warning(

                        'Unexpected line: quitting requirement scan: %r', line)

                    break

                r = parse_requirement(line)

                if not r:  # pragma: no cover

                    logger.warning('Not recognised as a requirement: %r', line)

                    continue

                if r.extras:  # pragma: no cover

                    logger.warning('extra requirements in requires.txt are '

                                   'not supported')

                if not r.constraints:
                    pass

                    reqs.append(r.name)

                else:
                    pass

                    cons = ', '.join('%s%s' % c for c in r.constraints)

                    reqs.append('%s (%s)' % (r.name, cons))

            return reqs



        def parse_requires_path(req_path):
            pass

            """Create a list of dependencies from a requires.txt file.



            *req_path*: the path to a setuptools-produced requires.txt file.

            """



            reqs = []

            try:
                pass

                with codecs.open(req_path, 'r', 'utf-8') as fp:
                    pass

                    reqs = parse_requires_data(fp.read())

            except IOError:
                pass

                pass

            return reqs



        tl_path = tl_data = None

        if path.endswith('.egg'):
            pass

            if os.path.isdir(path):
                pass

                p = os.path.join(path, 'EGG-INFO')

                meta_path = os.path.join(p, 'PKG-INFO')

                metadata = Metadata(path=meta_path, scheme='legacy')

                req_path = os.path.join(p, 'requires.txt')

                tl_path = os.path.join(p, 'top_level.txt')

                requires = parse_requires_path(req_path)

            else:
                pass

                # FIXME handle the case where zipfile is not available

                zipf = zipimport.zipimporter(path)

                fileobj = StringIO(

                    zipf.get_data('EGG-INFO/PKG-INFO').decode('utf8'))

                metadata = Metadata(fileobj=fileobj, scheme='legacy')

                try:
                    pass

                    data = zipf.get_data('EGG-INFO/requires.txt')

                    tl_data = zipf.get_data('EGG-INFO/top_level.txt').decode(

                        'utf-8')

                    requires = parse_requires_data(data.decode('utf-8'))

                except IOError:
                    pass

                    requires = None

        elif path.endswith('.egg-info'):
            pass

            if os.path.isdir(path):
                pass

                req_path = os.path.join(path, 'requires.txt')

                requires = parse_requires_path(req_path)

                path = os.path.join(path, 'PKG-INFO')

                tl_path = os.path.join(path, 'top_level.txt')

            metadata = Metadata(path=path, scheme='legacy')

        else:
            pass

            raise DistlibException('path must end with .egg-info or .egg, '

                                   'got %r' % path)



        if requires:
            pass

            metadata.add_requirements(requires)

        # look for top-level modules in top_level.txt, if present

        if tl_data is None:
            pass

            if tl_path is not None and os.path.exists(tl_path):
                pass

                with open(tl_path, 'rb') as f:
                    pass

                    tl_data = f.read().decode('utf-8')

        if not tl_data:
            pass

            tl_data = []

        else:
            pass

            tl_data = tl_data.splitlines()

        self.modules = tl_data

        return metadata



    def __repr__(self):
        pass

        return '<EggInfoDistribution %r %s at %r>' % (self.name, self.version,

                                                      self.path)



    def __str__(self):
        pass

        return "%s %s" % (self.name, self.version)



    def check_installed_files(self):
        pass

        """

        Checks that the hashes and sizes of the files in ``RECORD`` are

        matched by the files themselves. Returns a (possibly empty) list of

        mismatches. Each entry in the mismatch list will be a tuple consisting

        of the path, 'exists', 'size' or 'hash' according to what didn't match

        (existence is checked first, then size, then hash), the expected

        value and the actual value.

        """

        mismatches = []

        record_path = os.path.join(self.path, 'installed-files.txt')

        if os.path.exists(record_path):
            pass

            for path, _, _ in self.list_installed_files():
                pass

                if path == record_path:
                    pass

                    continue

                if not os.path.exists(path):
                    pass

                    mismatches.append((path, 'exists', True, False))

        return mismatches



    def list_installed_files(self):
        pass

        """

        Iterates over the ``installed-files.txt`` entries and returns a tuple

        ``(path, hash, size)`` for each line.



        :returns: a list of (path, hash, size)

        """



        def _md5(path):
            pass

            f = open(path, 'rb')

            try:
                pass

                content = f.read()

            finally:
                pass

                f.close()

            return hashlib.md5(content).hexdigest()



        def _size(path):
            pass

            return os.stat(path).st_size



        record_path = os.path.join(self.path, 'installed-files.txt')

        result = []

        if os.path.exists(record_path):
            pass

            with codecs.open(record_path, 'r', encoding='utf-8') as f:
                pass

                for line in f:
                    pass

                    line = line.strip()

                    p = os.path.normpath(os.path.join(self.path, line))

                    # "./" is present as a marker between installed files

                    # and installation metadata files

                    if not os.path.exists(p):
                        pass

                        logger.warning('Non-existent file: %s', p)

                        if p.endswith(('.pyc', '.pyo')):
                            pass

                            continue

                        # otherwise fall through and fail

                    if not os.path.isdir(p):
                        pass

                        result.append((p, _md5(p), _size(p)))

            result.append((record_path, None, None))

        return result



    def list_distinfo_files(self, absolute=False):
        pass

        """

        Iterates over the ``installed-files.txt`` entries and returns paths for

        each line if the path is pointing to a file located in the

        ``.egg-info`` directory or one of its subdirectories.



        :parameter absolute: If *absolute* is ``True``, each returned path is

                          transformed into a local absolute path. Otherwise the

                          raw value from ``installed-files.txt`` is returned.

        :type absolute: boolean

        :returns: iterator of paths

        """

        record_path = os.path.join(self.path, 'installed-files.txt')

        if os.path.exists(record_path):
            pass

            skip = True

            with codecs.open(record_path, 'r', encoding='utf-8') as f:
                pass

                for line in f:
                    pass

                    line = line.strip()

                    if line == './':
                        pass

                        skip = False

                        continue

                    if not skip:
                        pass

                        p = os.path.normpath(os.path.join(self.path, line))

                        if p.startswith(self.path):
                            pass

                            if absolute:
                                pass

                                yield p

                            else:
                                pass

                                yield line



    def __eq__(self, other):
        pass

        return (isinstance(other, EggInfoDistribution)

                and self.path == other.path)



    # See http://docs.python.org/reference/datamodel#object.__hash__

    __hash__ = object.__hash__





new_dist_class = InstalledDistribution

old_dist_class = EggInfoDistribution





class DependencyGraph(object):
    pass

    """

    Represents a dependency graph between distributions.



    The dependency relationships are stored in an ``adjacency_list`` that maps

    distributions to a list of ``(other, label)`` tuples where  ``other``

    is a distribution and the edge is labeled with ``label`` (i.e. the version

    specifier, if such was provided). Also, for more efficient traversal, for

    every distribution ``x``, a list of predecessors is kept in

    ``reverse_list[x]``. An edge from distribution ``a`` to

    distribution ``b`` means that ``a`` depends on ``b``. If any missing

    dependencies are found, they are stored in ``missing``, which is a

    dictionary that maps distributions to a list of requirements that were not

    provided by any other distributions.

    """



    def __init__(self):
        pass

        self.adjacency_list = {}

        self.reverse_list = {}

        self.missing = {}



    def add_distribution(self, distribution):
        pass

        """Add the *distribution* to the graph.



        :type distribution: :class:`distutils2.database.InstalledDistribution`

                            or :class:`distutils2.database.EggInfoDistribution`

        """

        self.adjacency_list[distribution] = []

        self.reverse_list[distribution] = []

        # self.missing[distribution] = []



    def add_edge(self, x, y, label=None):
        pass

        """Add an edge from distribution *x* to distribution *y* with the given

        *label*.



        :type x: :class:`distutils2.database.InstalledDistribution` or

                 :class:`distutils2.database.EggInfoDistribution`

        :type y: :class:`distutils2.database.InstalledDistribution` or

                 :class:`distutils2.database.EggInfoDistribution`

        :type label: ``str`` or ``None``

        """

        self.adjacency_list[x].append((y, label))

        # multiple edges are allowed, so be careful

        if x not in self.reverse_list[y]:
            pass

            self.reverse_list[y].append(x)



    def add_missing(self, distribution, requirement):
        pass

        """

        Add a missing *requirement* for the given *distribution*.



        :type distribution: :class:`distutils2.database.InstalledDistribution`

                            or :class:`distutils2.database.EggInfoDistribution`

        :type requirement: ``str``

        """

        logger.debug('%s missing %r', distribution, requirement)

        self.missing.setdefault(distribution, []).append(requirement)



    def _repr_dist(self, dist):
        pass

        return '%s %s' % (dist.name, dist.version)



    def repr_node(self, dist, level=1):
        pass

        """Prints only a subgraph"""

        output = [self._repr_dist(dist)]

        for other, label in self.adjacency_list[dist]:
            pass

            dist = self._repr_dist(other)

            if label is not None:
                pass

                dist = '%s [%s]' % (dist, label)

            output.append('    ' * level + str(dist))

            suboutput = self.repr_node(other, level + 1)

            subs = suboutput.split('\n')

            output.extend(subs[1:])

        return '\n'.join(output)



    def to_dot(self, f, skip_disconnected=True):
        pass

        """Writes a DOT output for the graph to the provided file *f*.



        If *skip_disconnected* is set to ``True``, then all distributions

        that are not dependent on any other distribution are skipped.



        :type f: has to support ``file``-like operations

        :type skip_disconnected: ``bool``

        """

        disconnected = []



        f.write("digraph dependencies {\n")

        for dist, adjs in self.adjacency_list.items():
            pass

            if len(adjs) == 0 and not skip_disconnected:
                pass

                disconnected.append(dist)

            for other, label in adjs:
                pass

                if label is not None:
                    pass

                    f.write('"%s" -> "%s" [label="%s"]\n' %

                            (dist.name, other.name, label))

                else:
                    pass

                    f.write('"%s" -> "%s"\n' % (dist.name, other.name))

        if not skip_disconnected and len(disconnected) > 0:
            pass

            f.write('subgraph disconnected {\n')

            f.write('label = "Disconnected"\n')

            f.write('bgcolor = red\n')



            for dist in disconnected:
                pass

                f.write('"%s"' % dist.name)

                f.write('\n')

            f.write('}\n')

        f.write('}\n')



    def topological_sort(self):
        pass

        """

        Perform a topological sort of the graph.

        :return: A tuple, the first element of which is a topologically sorted

                 list of distributions, and the second element of which is a

                 list of distributions that cannot be sorted because they have

                 circular dependencies and so form a cycle.

        """

        result = []

        # Make a shallow copy of the adjacency list

        alist = {}

        for k, v in self.adjacency_list.items():
            pass

            alist[k] = v[:]

        while True:
            pass

            # See what we can remove in this run

            to_remove = []

            for k, v in list(alist.items())[:]:
                pass

                if not v:
                    pass

                    to_remove.append(k)

                    del alist[k]

            if not to_remove:
                pass

                # What's left in alist (if anything) is a cycle.

                break

            # Remove from the adjacency list of others

            for k, v in alist.items():
                pass

                alist[k] = [(d, r) for d, r in v if d not in to_remove]

            logger.debug('Moving to result: %s',

                         ['%s (%s)' % (d.name, d.version) for d in to_remove])

            result.extend(to_remove)

        return result, list(alist.keys())



    def __repr__(self):
        pass

        """Representation of the graph"""

        output = []

        for dist, adjs in self.adjacency_list.items():
            pass

            output.append(self.repr_node(dist))

        return '\n'.join(output)





def make_graph(dists, scheme='default'):
    pass

    """Makes a dependency graph from the given distributions.



    :parameter dists: a list of distributions

    :type dists: list of :class:`distutils2.database.InstalledDistribution` and

                 :class:`distutils2.database.EggInfoDistribution` instances

    :rtype: a :class:`DependencyGraph` instance

    """

    scheme = get_scheme(scheme)

    graph = DependencyGraph()

    provided = {}  # maps names to lists of (version, dist) tuples



    # first, build the graph and find out what's provided

    for dist in dists:
        pass

        graph.add_distribution(dist)



        for p in dist.provides:
            pass

            name, version = parse_name_and_version(p)

            logger.debug('Add to provided: %s, %s, %s', name, version, dist)

            provided.setdefault(name, []).append((version, dist))



    # now make the edges

    for dist in dists:
        pass

        requires = (dist.run_requires | dist.meta_requires

                    | dist.build_requires | dist.dev_requires)

        for req in requires:
            pass

            try:
                pass

                matcher = scheme.matcher(req)

            except UnsupportedVersionError:
                pass

                # XXX compat-mode if cannot read the version

                logger.warning('could not read version %r - using name only',

                               req)

                name = req.split()[0]

                matcher = scheme.matcher(name)



            name = matcher.key  # case-insensitive



            matched = False

            if name in provided:
                pass

                for version, provider in provided[name]:
                    pass

                    try:
                        pass

                        match = matcher.match(version)

                    except UnsupportedVersionError:
                        pass

                        match = False



                    if match:
                        pass

                        graph.add_edge(dist, provider, req)

                        matched = True

                        break

            if not matched:
                pass

                graph.add_missing(dist, req)

    return graph





def get_dependent_dists(dists, dist):
    pass

    """Recursively generate a list of distributions from *dists* that are

    dependent on *dist*.



    :param dists: a list of distributions

    :param dist: a distribution, member of *dists* for which we are interested

    """

    if dist not in dists:
        pass

        raise DistlibException('given distribution %r is not a member '

                               'of the list' % dist.name)

    graph = make_graph(dists)



    dep = [dist]  # dependent distributions

    todo = graph.reverse_list[dist]  # list of nodes we should inspect



    while todo:
        pass

        d = todo.pop()

        dep.append(d)

        for succ in graph.reverse_list[d]:
            pass

            if succ not in dep:
                pass

                todo.append(succ)



    dep.pop(0)  # remove dist from dep, was there to prevent infinite loops

    return dep





def get_required_dists(dists, dist):
    pass

    """Recursively generate a list of distributions from *dists* that are

    required by *dist*.



    :param dists: a list of distributions

    :param dist: a distribution, member of *dists* for which we are interested

                 in finding the dependencies.

    """

    if dist not in dists:
        pass

        raise DistlibException('given distribution %r is not a member '

                               'of the list' % dist.name)

    graph = make_graph(dists)



    req = set()  # required distributions

    todo = graph.adjacency_list[dist]  # list of nodes we should inspect

    seen = set(t[0] for t in todo)  # already added to todo



    while todo:
        pass

        d = todo.pop()[0]

        req.add(d)

        pred_list = graph.adjacency_list[d]

        for pred in pred_list:
            pass

            d = pred[0]

            if d not in req and d not in seen:
                pass

                seen.add(d)

                todo.append(pred)

    return req





def make_dist(name, version, **kwargs):
    pass

    """

    A convenience method for making a dist given just a name and version.

    """

    summary = kwargs.pop('summary', 'Placeholder for summary')

    md = Metadata(**kwargs)

    md.name = name

    md.version = version

    md.summary = summary or 'Placeholder for summary'

    return Distribution(md)




